.notifications-section {
    max-width: 600px;
}

.notifications-section h3 {
    margin: 0 0 1rem 0;
    color: #333;
    font-size: 1.1rem;
}

.toggle-group {
    margin-bottom: 2rem;
}

.toggle-item {
    display: grid;
    grid-template-columns: auto 1fr;
    grid-template-rows: auto auto;
    gap: 0 0.75rem;
    align-items: center;
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    grid-row: 1 / 3;
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

.toggle-label {
    font-weight: 500;
    color: #333;
}

.toggle-description {
    font-size: 0.85rem;
    color: #888;
    grid-column: 2;
}

.section-description {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
    margin-bottom: 1.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    cursor: pointer;
    transition: background 0.2s;
}

.channel-item:hover {
    background: #f5f5f5;
}

.channel-item input[type="checkbox"] {
    accent-color: #1976d2;
}

.button-group {
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #1976d2;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-weight: 500;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast.error {
    background: #fbe9e7;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

.loading {
    color: #666;
    font-style: italic;
}

