@namespace sv_1f114f7f4be742c699afb66797675580.Components.Pages.Settings
@using sv_1f114f7f4be742c699afb66797675580.Services
@inject ISettingsService SettingsService

<div class="security-section">
    @if (_loading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="panel">
            <div class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
                <h3>Change Password</h3>
                <span class="expand-icon">@(_passwordExpanded ? "▼" : "▶")</span>
            </div>
            @if (_passwordExpanded)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm New Password</label>
                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                    </div>
                    @if (_passwordError is not null)
                    {
                        <div class="toast error">@_passwordError</div>
                    }
                    @if (_passwordSuccess)
                    {
                        <div class="toast success">✓ Password updated successfully!</div>
                    }
                    <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @(_changingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="panel">
            <div class="panel-body tfa-row">
                <div class="tfa-info">
                    <h3>Two-Factor Authentication</h3>
                    <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                        @(_twoFactorEnabled ? "● Enabled" : "○ Disabled")
                    </span>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="panel">
            <h3>Active Sessions</h3>
            @if (_settings?.Sessions.Count > 0)
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _settings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != _settings.Sessions[0])
                                    {
                                        @if (_confirmingRevoke == session.Id)
                                        {
                                            <span class="revoke-confirm">
                                                Revoke?
                                                <button class="btn-danger-sm" @onclick="() => RevokeSessionAsync(session.Id)">Yes</button>
                                                <button class="btn-cancel-sm" @onclick="() => _confirmingRevoke = null">No</button>
                                            </span>
                                        }
                                        else
                                        {
                                            <button class="btn-outline-danger" @onclick="() => _confirmingRevoke = session.Id">
                                                Revoke
                                            </button>
                                        }
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
            else
            {
                <p class="no-data">No active sessions found.</p>
            }
        </div>

        @if (_settings?.LastPasswordChange is not null)
        {
            <p class="last-changed">Last password change: @_settings.LastPasswordChange.Value.ToString("f")</p>
        }
    }
</div>

@code {
    private bool _loading = true;
    private SecuritySettings? _settings;

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _passwordError;
    private bool _passwordSuccess;

    private bool _twoFactorEnabled;
    private string? _confirmingRevoke;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password cannot be empty.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordError = ex.Message;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            _settings = _settings! with
            {
                Sessions = _settings.Sessions.Where(s => s.Id != sessionId).ToList()
            };
            _confirmingRevoke = null;
        }
        catch (Exception ex)
        {
            _passwordError = $"Failed to revoke session: {ex.Message}";
        }
    }
}

