toolArgs.file_text:
.security-section {
    max-width: 700px;
}

.panel {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.25rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem;
    cursor: pointer;
    user-select: none;
    background: #fafafa;
    border-bottom: 1px solid #e0e0e0;
}

.panel-header:hover {
    background: #f0f0f0;
}

.panel-header h3 {
    margin: 0;
    font-size: 1rem;
}

.expand-icon {
    color: #888;
    font-size: 0.8rem;
}

.panel-body {
    padding: 1.25rem;
}

.panel > h3 {
    margin: 0;
    padding: 1rem 1.25rem;
    font-size: 1rem;
    border-bottom: 1px solid #e0e0e0;
    background: #fafafa;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.3rem;
    color: #333;
    font-size: 0.9rem;
}

.form-group input {
    width: 100%;
    max-width: 350px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.tfa-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.tfa-info {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.tfa-info h3 {
    margin: 0;
    font-size: 1rem;
}

.status-indicator {
    font-size: 0.85rem;
    font-weight: 500;
}

.status-indicator.enabled {
    color: #2e7d32;
}

.status-indicator.disabled {
    color: #999;
}

.switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background: #ccc;
    border-radius: 24px;
    transition: 0.3s;
}

.slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.3s;
}

.switch input:checked + .slider {
    background: #1976d2;
}

.switch input:checked + .slider::before {
    transform: translateX(20px);
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem 1rem;
    text-align: left;
    border-bottom: 1px solid #f0f0f0;
}

.sessions-table th {
    font-weight: 600;
    font-size: 0.85rem;
    color: #666;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.sessions-table tbody tr:hover {
    background: #f9f9f9;
}

.current-badge {
    font-size: 0.8rem;
    background: #e3f2fd;
    color: #1976d2;
    padding: 0.2rem 0.6rem;
    border-radius: 10px;
    font-weight: 500;
}

.btn-outline-danger {
    padding: 0.3rem 0.75rem;
