arguments.file_text:
@namespace sv_1f114f7f4be742c699afb66797675580.Components.Pages.Settings
@using sv_1f114f7f4be742c699afb66797675580.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <!-- Theme -->
        <div class="setting-group">
            <h3>Theme</h3>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-item @(_theme == theme.Value ? "selected" : "")">
                        <input type="radio" name="theme" value="@theme.Value"
                               checked="@(_theme == theme.Value)"
                               @onchange="() => _theme = theme.Value" />
                        <span class="radio-icon">@theme.Icon</span>
                        <span>@theme.Label</span>
                    </label>
                }
            </div>
        </div>

        <!-- Font Size -->
        <div class="setting-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-item @(_fontSize == size.Value ? "selected" : "")">
                        <input type="radio" name="fontSize" value="@size.Value"
                               checked="@(_fontSize == size.Value)"
                               @onchange="() => _fontSize = size.Value" />
                        <span style="font-size: @size.Preview">Aa</span>
                        <span>@size.Label</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language -->
        <div class="setting-group">
            <h3>Language</h3>
            <select @bind="_language" class="language-select">
                @foreach (var lang in _languages)
                {
                    <option value="@lang.Value">@lang.Label</option>
                }
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="setting-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" />
                <div>
                    <span class="toggle-label">Compact Mode</span>
                    <span class="toggle-description">Reduce spacing and padding for denser content</span>
                </div>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="setting-group">
            <h3>Preview</h3>
            <div class="preview-area @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">
                    This is how your content will look with the selected appearance settings.
                    Adjust theme, font size, and compact mode to see changes in real time.
                </p>
                <div class="preview-actions">
                    <span class="preview-btn">Button</span>
                    <span class="preview-link">Link</span>
                </div>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">✓ Appearance settings saved!</div>
        }
        @if (_errorMessage is not null)
        {
            <div class="toast error">@_errorMessage</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;
    private string? _errorMessage;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private record ThemeOption(string Value, string Label, string Icon);
    private record FontSizeOption(string Value, string Label, string Preview);
    private record LanguageOption(string Value, string Label);

    private static readonly ThemeOption[] _themes =
    [
        new("Light", "Light", "☀️"),
        new("Dark", "Dark", "🌙"),
        new("System", "System", "💻")
    ];

    private static readonly FontSizeOption[] _fontSizes =
    [
        new("Small", "Small", "0.8rem"),
        new("Medium", "Medium", "1rem"),
        new("Large", "Large", "1.2rem")
    ];

    private static readonly LanguageOption[] _languages =
    [
        new("en", "English"),
        new("es", "Español"),
        new("fr", "Français"),
        new("de", "Deutsch"),
        new("ja", "日本語"),
        new("zh", "中文"),
        new("pt", "Português")
    ];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        _errorMessage = null;

        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _showSuccess = true;
            _ = HideSuccessAfterDelay();
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.appearance-section {
    max-width: 600px;
}

.setting-group {
    margin-bottom: 1.75rem;
}

.setting-group h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1rem;
    color: #333;
}

.radio-group {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1rem;
    border: 2px solid #e0e0e0;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s;
    user-select: none;
}

.radio-item:hover {
    border-color: #90caf9;
    background: #f5f9ff;
}

.radio-item.selected {
    border-color: #1976d2;
    background: #e3f2fd;
}

.radio-item input[type="radio"] {
    display: none;
}

.radio-icon {
    font-size: 1.2rem;
}

.language-select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    min-width: 200px;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

.toggle-label {
    display: block;
    font-weight: 500;
    color: #333;
}

.toggle-description {
    display: block;
    font-size: 0.85rem;
    color: #888;
}

/* Live Preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    transition: all 0.3s ease;
}

.preview-area.theme-light {
    background: #ffffff;
    color: #333;
}

.preview-area.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
}

.preview-area.theme-system {
    background: #f8f9fa;
    color: #333;
}

.preview-area.font-small {
    font-size: 0.85rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.15rem;
}

.preview-area.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    font-weight: 600;
    font-size: 1.2em;
    margin-bottom: 0.5rem;
}

.preview-text {
