toolArgs.file_text:
.appearance-section {
    max-width: 600px;
}

.setting-group {
    margin-bottom: 1.75rem;
}

.setting-group h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1rem;
    color: #333;
}

.radio-group {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1rem;
    border: 2px solid #e0e0e0;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s;
    user-select: none;
}

.radio-item:hover {
    border-color: #90caf9;
    background: #f5f9ff;
}

.radio-item.selected {
    border-color: #1976d2;
    background: #e3f2fd;
}

.radio-item input[type="radio"] {
    display: none;
}

.radio-icon {
    font-size: 1.2rem;
}

.language-select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    min-width: 200px;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

.toggle-label {
    display: block;
    font-weight: 500;
    color: #333;
}

.toggle-description {
    display: block;
    font-size: 0.85rem;
    color: #888;
}

/* Live Preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    transition: all 0.3s ease;
}

.preview-area.theme-light {
    background: #ffffff;
    color: #333;
}

.preview-area.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
}

.preview-area.theme-system {
    background: #f8f9fa;
    color: #333;
}

.preview-area.font-small {
    font-size: 0.85rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.15rem;
}

.preview-area.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    font-weight: 600;
    font-size: 1.2em;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin: 0.5rem 0;
    line-height: 1.5;
}

.preview-actions {
    margin-top: 0.75rem;
    display: flex;
    gap: 1rem;
}

.preview-btn {
    padding: 0.35rem 0.85rem;
    background: #1976d2;
    color: white;
    border-radius: 4px;
    font-size: 0.9em;
}

.preview-link {
    color: #1976d2;
    text-decoration: underline;
    font-size: 0.9em;
}

.theme-dark .preview-link {
    color: #64b5f6;
}

.button-group {
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #1976d2;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-weight: 500;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast.error {
    background: #fbe9e7;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

.loading {
    color: #666;
    font-style: italic;
}

