arguments.file_text:
@page "/settings"
@using sv_1f114f7f4be742c699afb66797675580.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        <h2>@_activeSection</h2>

        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 60px);
    background: #fff;
}

.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    max-width: 900px;
}

.settings-content h2 {
    margin: 0 0 1.5rem 0;
    font-size: 1.5rem;
    color: #222;
    border-bottom: 1px solid #eee;
    padding-bottom: 0.75rem;
}

